	//闁圭顦抽惁搴㈠閺夊簱鍋撻梻瀵哥煠濠㈠爢鍐ㄧ厒閻忓繐绻戠敮鎾存償韫囨洘鐣遍柛姘墛绾墎鎸ч悧鍫€婇柛鎺擃殙閵?
	After_Myfc_Rival_Legal_Move_Values* after_myfc_rival_legal_move_values = new After_Myfc_Rival_Legal_Move_Values;
	memset(after_myfc_rival_legal_move_values, 0, sizeof(After_Myfc_Rival_Legal_Move_Values));
	Legal_moves* legal_moves = make_move(side, 0, after_myfc_rival_legal_move_values);
	Legal_moves* rival_legal_moves = NULL;
