			zobrist_key ^= zobrist[0][final_legal_moves->moves[v].path[final_legal_moves->moves[v].length - 1].y][final_legal_moves->moves[v].path[final_legal_moves->moves[v].length - 1].x];
			//閻忓繐妫欓ˉ鎰偓娑欏姉缁捇鎮欒ぐ鎺濇澒闁艰褰冩慨鐐哄礂椤ㄢ偓obrist
			zobrist_key ^= zobrist[side][final_legal_moves->moves[v].path[final_legal_moves->moves[v].length - 1].y][final_legal_moves->moves[v].path[final_legal_moves->moves[v].length - 1].x];
			//閻忓繐妫欓ˉ鎰偓娑欏姌閹癸綁鎮欓崷顓犳瀭濞戞捁娅ｉ埞鏍冀?
			qp[final_legal_moves->moves[v].path[0].y][final_legal_moves->moves[v].path[0].x] = 0;
			//闁哄洤鐡ㄩ弻濠偽涚€ｎ亞鎽嶉悹褔顥撻崑锝嗙▔閾忓厜鏁勯柡宥堝亹濞堟啇obrist
			zobrist_key ^= zobrist[side][final_legal_moves->moves[v].path[0].y][final_legal_moves->moves[v].path[0].x];
			//闁哄洤鐡ㄩ弻濠偽涚€ｎ亞鎽嶅Λ鐗堢矎婢瑰﹪鎯冮崜鎶゜rist
			zobrist_key ^= zobrist[0][final_legal_moves->moves[v].path[0].y][final_legal_moves->moves[v].path[0].x];
